private theorem auxiliary_gauge_single (i : Fin 6 × Fin 12) (mu : Fin 4) (a : Fin 12) (z : ℂ) :
    (Matrix.single (gaugeAuxiliaryIndex i) (gaugeSlot mu a) z).submatrix gaugeAuxiliaryIndex nativeRestIndex=
      Matrix.single i (gaugeRestIndex mu a) z

private theorem colour_read (d mu : Fin 4) (pair a : Fin 6) (i : Fin 12) (p : Fin 4 → ℂ) (r : Fin 217 → ℂ) :
    (derivativeColourMatrix d mu pair p*ᵥr) (a,i)=
      if pair=a then p d*auxiliaryLieReader (fun j => r (gaugeRestIndex mu j)) i else 0

private theorem literal_diff_append (a b : List (NativeJetIndex × NativeJetIndex × ℝ)) (p : Fin 4 → ℂ) :
    nativeLiteralFourier (a++b) p-nativeLiteralFourier (a++b) 0=
      (nativeLiteralFourier a p-nativeLiteralFourier a 0)+(nativeLiteralFourier b p-nativeLiteralFourier b 0)

private theorem literal_cons (t : NativeJetIndex × NativeJetIndex × ℝ)
    (ts : List (NativeJetIndex × NativeJetIndex × ℝ)) (p : Fin 4 → ℂ) :
    nativeLiteralFourier (t::ts) p=nativeLiteralFourier [t] p+nativeLiteralFourier ts p

private theorem lie_reader_curl (p : Fin 4 → ℂ) (r : Fin 217 → ℂ) (pair : Fin 6) (i : Fin 12) :
    auxiliaryLieReader (fun a => nativeMomentumCurl p (fun mu => r (gaugeRestIndex mu a)) pair) i=
      nativeMomentumCurl p (fun mu => auxiliaryLieReader (fun a => r (gaugeRestIndex mu a)) i) pair

private theorem actual_rest_em_projection (r : Fin 217 → ℂ) (mu : Fin 4) :
    (nativeEMRestInsertion.transpose*ᵥr) mu=
      (1/2 : ℂ)*(-r (gaugeRestIndex mu 6)+r (gaugeRestIndex mu 7)-r (gaugeRestIndex mu 11))
